CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, seek_job_id TEXT NOT NULL, title TEXT NOT NULL, company TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', salary_range TEXT, work_type TEXT, work_arrangement TEXT, description_snippet TEXT NOT NULL DEFAULT '', full_description TEXT, job_url TEXT NOT NULL DEFAULT '', date_posted TEXT, date_scraped TEXT NOT NULL, pipeline_status TEXT NOT NULL DEFAULT 'inbox', notes TEXT, updated_at TEXT NOT NULL, triage_source TEXT NOT NULL DEFAULT 'manual', search_profile_id TEXT, auto_hidden_at TEXT, UNIQUE(user_id, seek_job_id));
CREATE INDEX jobs_user_status ON jobs(user_id, pipeline_status);
CREATE TABLE resume_profile (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, raw_text TEXT NOT NULL DEFAULT '', skills_technical TEXT NOT NULL DEFAULT '[]', skills_soft TEXT NOT NULL DEFAULT '[]', years_experience REAL, education TEXT NOT NULL DEFAULT '[]', certifications TEXT NOT NULL DEFAULT '[]', previous_titles TEXT NOT NULL DEFAULT '[]', industries TEXT NOT NULL DEFAULT '[]', summary TEXT, file_path TEXT, file_name TEXT, file_type TEXT, updated_at TEXT NOT NULL);
CREATE TABLE job_matches (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, resume_profile_id TEXT, match_score REAL NOT NULL, skill_match_percentage REAL, recommendation TEXT NOT NULL DEFAULT '', reasoning TEXT, pros TEXT NOT NULL DEFAULT '[]', cons TEXT NOT NULL DEFAULT '[]', gaps TEXT NOT NULL DEFAULT '[]', strategic_advice TEXT, scored_at TEXT NOT NULL, grade TEXT, why_apply TEXT, risks TEXT, agent TEXT, agent_version TEXT, veto_reasons TEXT DEFAULT '[]', scores TEXT, dealbreaker_hits TEXT DEFAULT '[]', concerns TEXT DEFAULT '[]', UNIQUE(user_id, job_id, resume_profile_id));
CREATE TABLE job_artifacts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, artifact_type TEXT NOT NULL, content TEXT NOT NULL, agent TEXT NOT NULL, version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE candidate_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, job_goals TEXT, career_direction TEXT, target_titles TEXT NOT NULL DEFAULT '[]', target_industries TEXT NOT NULL DEFAULT '[]', excluded_titles TEXT NOT NULL DEFAULT '[]', salary_min REAL, salary_target REAL, currency TEXT NOT NULL DEFAULT 'AUD', locations TEXT NOT NULL DEFAULT '[]', work_arrangements TEXT NOT NULL DEFAULT '[]', work_types TEXT NOT NULL DEFAULT '[]', mandatory_qualifications TEXT NOT NULL DEFAULT '[]', dealbreakers TEXT NOT NULL DEFAULT '[]', verified_experience TEXT, policy_strong INTEGER NOT NULL DEFAULT 80, policy_review INTEGER NOT NULL DEFAULT 75, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE search_profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, target_titles TEXT NOT NULL DEFAULT '[]', locations TEXT NOT NULL DEFAULT '[]', salary_min REAL, active INTEGER NOT NULL DEFAULT 1, last_run_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE pipeline_runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, search_profile_id TEXT, status TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, jobs_found INTEGER NOT NULL DEFAULT 0, jobs_new INTEGER NOT NULL DEFAULT 0, jobs_scored INTEGER NOT NULL DEFAULT 0, summary TEXT, error TEXT);
CREATE TABLE resume_revisions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, revision_number INTEGER NOT NULL, raw_text TEXT NOT NULL, content_hash TEXT, approved_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE candidate_facts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, fact_type TEXT, value TEXT, source TEXT, created_at TEXT NOT NULL);
CREATE TABLE document_revisions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT REFERENCES jobs(id) ON DELETE CASCADE, document_type TEXT NOT NULL, revision_number INTEGER NOT NULL, label TEXT, content TEXT NOT NULL, content_hash TEXT NOT NULL, truth_check_status TEXT NOT NULL DEFAULT 'passed', truth_check TEXT, approval_status TEXT NOT NULL DEFAULT 'pending', source_resume_revision_id TEXT, supersedes_revision_id TEXT, storage_path TEXT, agent_version TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE application_packages (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id) ON DELETE CASCADE, resume_document_revision_id TEXT, cover_letter_document_revision_id TEXT, resume_content_hash TEXT, cover_letter_content_hash TEXT, checklist TEXT NOT NULL DEFAULT '[]', package_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE approval_decisions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, decision TEXT NOT NULL, expected_hash TEXT, comment TEXT, created_at TEXT NOT NULL);
CREATE TABLE application_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, event_type TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE assistant_runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, summary TEXT, created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE assistant_tasks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, run_id TEXT, task_type TEXT NOT NULL, status TEXT NOT NULL, payload TEXT, result TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE assistant_recommendations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, band TEXT, status TEXT, content TEXT, created_at TEXT NOT NULL);
CREATE TABLE job_revisions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT NOT NULL);
